INSERT INTO RESERVATION (RESERVATION_ID, USER_ID, TREATMENT_ID, STATUS, STARTS_AT, ENDS_AT, APPLIED_PRICE, DEPOSIT, HOLD_EXPIRES_AT, CONFIRMED_AT, CUSTOMER_REQUEST, CREATED_AT, UPDATED_AT)
SELECT SEQ_RESERVATION.NEXTVAL, u.USER_ID, t.TREATMENT_ID, 'CONFIRMED', TIMESTAMP '2026-11-05 12:00:00', TIMESTAMP '2026-11-05 12:30:00', 30000, 20000, TIMESTAMP '2026-11-01 11:36:00', TIMESTAMP '2026-11-01 11:33:00', '주차 가능한지 알려주세요', TIMESTAMP '2026-11-01 11:31:00', TIMESTAMP '2026-11-01 11:33:00'
FROM SHOP s JOIN TREATMENT t ON t.SHOP_ID = s.SHOP_ID AND t.NAME = '진정 모델링팩' AND t.TREATMENT_TYPE = 'NORMAL' AND t.STATUS = 'ACTIVE' JOIN APP_USER u ON u.LOGIN_ID = 'demo170_c28'
WHERE s.LOGIN_ID = 'demo164_s14'
  AND NOT EXISTS (SELECT 1 FROM TREATMENT o JOIN RESERVATION r ON r.TREATMENT_ID = o.TREATMENT_ID WHERE o.SHOP_ID = s.SHOP_ID AND r.STARTS_AT < TIMESTAMP '2026-11-05 12:30:00' AND r.ENDS_AT > TIMESTAMP '2026-11-05 12:00:00' AND r.STATUS IN ('HOLD', 'CONFIRMED', 'CANCEL_PENDING'))
