SELECT SEQ_RESERVATION.NEXTVAL, u.USER_ID, t.TREATMENT_ID, 'CONFIRMED', TIMESTAMP '2026-11-05 11:30:00', TIMESTAMP '2026-11-05 12:00:00', 30000, 20000, TIMESTAMP '2026-11-04 19:52:00', TIMESTAMP '2026-11-04 19:49:00', NULL, TIMESTAMP '2026-11-04 19:47:00', TIMESTAMP '2026-11-04 19:49:00'
